insert into public.fa_catalog_players(id,name,club,league,nationality,primary_position,secondary_positions,overall,player_type,enabled,metadata)
select id,name,club,league,nationality,primary_position,secondary_positions,overall,'ACTIVE',true,metadata_patch
from incoming
on conflict (id) do update set
  name=excluded.name,
  club=excluded.club,
  league=excluded.league,
  nationality=excluded.nationality,
  primary_position=excluded.primary_position,
  secondary_positions=excluded.secondary_positions,
  overall=excluded.overall,
  enabled=true,
  metadata=coalesce(public.fa_catalog_players.metadata,'{}'::jsonb) || excluded.metadata;

