update public.fa_catalog_players c
set metadata = coalesce(c.metadata,'{}'::jsonb) || review.metadata_patch
from review
where c.id = review.id;

update public.fa_players p
set club = c.club,
    league = c.league,
    nationality = c.nationality,
    primary_position = c.primary_position,
    secondary_positions = c.secondary_positions,
    overall = c.overall,
    metadata = coalesce(p.metadata,'{}'::jsonb) || jsonb_build_object('catalog_rating_status', c.metadata->>'rating_status')
from public.fa_catalog_players c
where p.catalog_id = c.id;

create or replace function public.fa_start_next_auction(p_room_id uuid)
 returns jsonb
 language plpgsql
 security definer
 set search_path to ''
as $function$
declare
  v_user uuid := auth.uid();
  v_room public.fa_rooms%rowtype;
  v_catalog public.fa_catalog_players%rowtype;
  v_room_player_id text;
  v_auction public.fa_auctions%rowtype;
begin
  if v_user is null then raise exception 'authentication required'; end if;
  select * into v_room from public.fa_rooms where id = p_room_id for update;
  if not found then raise exception 'room not found'; end if;
  if v_room.host_user_id <> v_user then raise exception 'host only'; end if;
  if exists (select 1 from public.fa_auctions a where a.room_id = p_room_id and a.status in ('interest','bidding')) then
    raise exception 'an auction is already active';
  end if;
  if (select count(*) from public.fa_room_members m where m.room_id = p_room_id) < 2 then
    raise exception 'at least two players are required';
  end if;

  if not exists (select 1 from public.fa_room_members m where m.room_id=p_room_id and not m.squad_finalized) then
    update public.fa_rooms set status='squads' where id=p_room_id;
    return null;
  end if;

  select c.* into v_catalog
  from public.fa_catalog_players c
  where c.enabled = true
    and not exists (
      select 1 from public.fa_players p where p.room_id = p_room_id and p.catalog_id = c.id
    )
    and exists (
      select 1 from public.fa_room_members m
      where m.room_id=p_room_id
        and not m.squad_finalized
        and private.fa_member_can_take_position(m.id, c.primary_position)
    )
  order by random()
  limit 1;

  if v_catalog.id is null then raise exception 'no eligible catalog players available'; end if;

  v_room_player_id := extensions.gen_random_uuid()::text;
  insert into public.fa_players(
    id, room_id, created_by, catalog_id, name, short_name, club, league, nationality,
    primary_position, secondary_positions, overall, player_type, image_url, metadata
  )
  values (
    v_room_player_id, p_room_id, v_user, v_catalog.id, v_catalog.name, v_catalog.name, v_catalog.club,
    v_catalog.league, v_catalog.nationality, v_catalog.primary_position, v_catalog.secondary_positions,
    v_catalog.overall, v_catalog.player_type, v_catalog.image_url,
    jsonb_build_object('catalog_id', v_catalog.id, 'legend_region', v_catalog.legend_region, 'rating_status', v_catalog.metadata->>'rating_status')
  );

  update public.fa_rooms set status = 'auction' where id = p_room_id;
  insert into public.fa_auctions(room_id, player_id)
  values (p_room_id, v_room_player_id)
  returning * into v_auction;

  insert into public.fa_player_interest(auction_id, member_id, wants)
  select v_auction.id, m.id, false
  from public.fa_room_members m
  where m.room_id=p_room_id
    and not private.fa_member_can_take_position(m.id, v_catalog.primary_position)
  on conflict do nothing;

  return to_jsonb(v_auction);
end;
$function$;
